Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

(* [comment removed for export] *)
Definition bge_m_exit (sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a7 s2 s3 s4 s6 s8 s9 s10 s11 t3 t5 t6 : word) (F : bvmap 5 word)
    (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' a1' a2' a6' s5' s7' t4' : word) (F' : bvmap 5 word) (fc' : bv 32),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 a0' a1' a2' a3 a4 a5 a6' a7 s2 s3 s4 s5' s6 s7' s8 s9 s10 s11 t3 t4' t5 t6)
             F' (Z_to_bv 64 0xc4a0c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc'.

Lemma bge_m_loop : forall (k : nat) (mm : Z)
    (sp gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a7 s2 s4 s5 s7 s8 s9 s10 s11 t3 t6 : word) F fc (m : mem) (D N P KR RR sx c : Z),
  Z.of_nat k = sx - mm -> 0 <= mm -> (1 <= k)%nat -> 0 < sx <= 20000 -> 0 <= c < 256 -> frm0 fc ->
  0 < D -> D mod 4 = 0 -> N mod 4 = 0 -> D + N <= 2^47 -> (D + N <= 0x7fff7000 \/ 0x10007fff8000 <= D) -> D <= P -> P + sx <= D + N ->
  0 < KR -> KR mod 16 = 0 -> KR + 4 * sx <= 2^47 -> (KR + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= KR) ->
  0 < RR -> RR mod 16 = 0 -> RR + 1024 <= 2^47 -> (RR + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= RR) ->
  wr_at asegs m D N -> acc asegs m D N -> wr_at asegs m KR (4 * sx) -> acc asegs m KR (4 * sx) ->
  wr_at asegs m RR 1024 -> acc asegs m RR 1024 -> mem_inv asegs m ->
  evt asegs (bge_m_exit sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a7 s2 (Z_to_bv 64 RR) s4 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3 (Z_to_bv 64 c) t6 F m)
    (MS (mkR (Z_to_bv 64 (P + mm)) sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (KR + 4 * mm)) a2 a3 a4 a5 (Z_to_bv 64 (KR + 4 * mm)) a7
             s2 (Z_to_bv 64 RR) s4 s5 (Z_to_bv 64 2147450880) s7 s8 s9 s10 s11 t3 (Z_to_bv 64 (sx - mm)) (Z_to_bv 64 c) t6)
