(* [comment removed for export] *)
Definition bge_k_exit (sp gp tp t0 t2 s0 s1 a3 a4 a5 a7 s2 s4 s6 s8 s9 s10 s11 t5 t6 : word) (F : bvmap 5 word)
    (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t1' a0' a1' a2' a6' s3' s5' s7' t3' t4' : word) (F' : bvmap 5 word) (fc' : bv 32),
    ms' = MS (mkR ra' sp gp tp t0 t1' t2 s0 s1 a0' a1' a2' a3 a4 a5 a6' a7 s2 s3' s4 s5' s6 s7' s8 s9 s10 s11 t3' t4' t5 t6)
             F' (Z_to_bv 64 0xc4b2c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc'.

(* [comment removed for export] *)
Definition bge_row (m : mem) (sx r : Z) : Prop :=
  0 < r /\ r mod 16 = 0 /\ r + 4 * sx <= 2^47 /\ (r + 4 * sx <= 0x7fff7000 \/ 0x10007fff8000 <= r)
  /\ wr_at asegs m r (4 * sx) /\ acc asegs m r (4 * sx).

Lemma bge_k_loop : forall (n : nat) (k : Z)
    (ra sp gp tp t0 s0 s1 a0 a1 a2 a3 a6 a7 s2 s3 s4 s5 s7 s9 t4 : word) F fc (m : mem)
    (D N PB W4 S8 ki datai kr datar RR sy sx c : Z) (rowsi : list Z),
  Z.of_nat n = sy - k -> 0 <= k -> (1 <= n)%nat -> 0 < sy <= 20000 -> 0 < sx <= 20000 -> 0 <= c < 256 -> frm0 fc ->
