  g_S1 : Z; g_PW : Z; g_PH : Z; g_PSY : Z; g_PSX : Z; g_PCY : Z; g_PCX : Z; g_S8 : Z;
  g_D : Z; g_N : Z; g_DD : Z; g_ND : Z;
  g_ki : Z; g_datai : Z; g_rowsi : list Z; g_kr : Z; g_datar : Z; g_RR : Z;
  g_w : Z; g_h : Z; g_sy : Z; g_sx : Z; g_cy : Z; g_cx : Z; g_wplt : Z; g_wpld : Z; g_ht : Z }.

Definition bgp_ok (p : bgp) : Prop :=
  0 < g_w p <= 2^26 /\ 0 < g_h p <= 2^26 /\ 0 < g_sy p <= 20000 /\ 0 < g_sx p <= 20000 /\ 0 <= g_cy p < g_sy p /\ 0 <= g_cx p < g_sx p
  /\ 0 < g_wplt p /\ 0 < g_wpld p /\ g_w p + g_sx p <= 4 * g_wplt p /\ g_w p <= 4 * g_wpld p /\ g_h p + g_sy p <= g_ht p
  /\ g_N p = 4 * (g_wplt p * g_ht p) /\ g_ND p = 4 * (g_wpld p * g_h p) /\ g_wplt p * g_ht p <= 2^26 /\ g_wpld p * g_h p <= 2^26
  /\ 0 < g_D p /\ g_D p mod 4 = 0 /\ g_D p + g_N p <= 2^47 /\ (g_D p + g_N p <= 0x7fff7000 \/ 0x10007fff8000 <= g_D p)
  /\ 0 < g_DD p /\ g_DD p mod 4 = 0 /\ g_DD p + g_ND p <= 2^47 /\ (g_DD p + g_ND p <= 0x7fff7000 \/ 0x10007fff8000 <= g_DD p)
  /\ 0 < g_ki p /\ g_ki p mod 16 = 0 /\ g_ki p + 24 <= 2^47 /\ 0 < g_datai p /\ g_datai p mod 16 = 0 /\ g_datai p + 8 * g_sy p <= 2^47
  /\ Z.of_nat (length (g_rowsi p)) = g_sy p
  /\ 0 < g_kr p /\ g_kr p mod 16 = 0 /\ g_kr p + 24 <= 2^47 /\ 0 < g_datar p /\ g_datar p mod 16 = 0 /\ g_datar p + 8 <= 2^47
  /\ 0 <= g_S1 p /\ g_S1 p + 128 <= 2^47.

(* [comment removed for export] *)
Definition bge_ro (p : bgp) (m : mem) : Prop :=
  rw_cells asegs m (g_S1 p + 40) [C8 (Z_to_bv 64 (g_wpld p))] /\ rw_cells asegs m (g_S1 p + 48) [C8 (Z_to_bv 64 (g_DD p))]
  /\ rw_cells asegs m (g_S1 p + 56) [C8 (Z_to_bv 64 (g_PH p))] /\ rw_cells asegs m (g_S1 p + 72) [C8 (Z_to_bv 64 (g_PSX p))]
  /\ rw_cells asegs m (g_S1 p + 80) [C8 (Z_to_bv 64 (g_PCX p))] /\ rw_cells asegs m (g_S1 p + 88) [C8 (Z_to_bv 64 (g_wplt p))]
  /\ rw_cells asegs m (g_S1 p + 96) [C8 (Z_to_bv 64 (g_D p))] /\ rw_cells asegs m (g_S1 p + 104) [C8 (Z_to_bv 64 (g_PCY p))]
  /\ rw_cells asegs m (g_S1 p + 120) [C8 (Z_to_bv 64 (g_PSY p))]
  /\ rw_cells asegs m (g_PW p) [C4 (Z_to_bv 64 (g_w p))] /\ rw_cells asegs m (g_PH p) [C4 (Z_to_bv 64 (g_h p))]
  /\ rw_cells asegs m (g_PSY p) [C4 (Z_to_bv 64 (g_sy p))] /\ rw_cells asegs m (g_PSX p) [C4 (Z_to_bv 64 (g_sx p))]
  /\ rw_cells asegs m (g_PCY p) [C4 (Z_to_bv 64 (g_cy p))] /\ rw_cells asegs m (g_PCX p) [C4 (Z_to_bv 64 (g_cx p))]
  /\ rw_cells asegs m (g_S8 p) [C8 (Z_to_bv 64 (g_ki p))]
  /\ acc asegs m (g_ki p) 24 /\ rw_cells asegs m (g_ki p + 16) [C8 (Z_to_bv 64 (g_datai p))] /\ acc asegs m (g_datai p) (8 * g_sy p)
  /\ u64arr asegs m (g_datai p) (map (Z_to_bv 64) (g_rowsi p)) /\ Forall (bge_row m (g_sx p)) (g_rowsi p)
  /\ acc asegs m (g_kr p) 24 /\ rw_cells asegs m (g_kr p + 16) [C8 (Z_to_bv 64 (g_datar p))] /\ acc asegs m (g_datar p) 8
  /\ rw_cells asegs m (g_datar p) [C8 (Z_to_bv 64 (g_RR p))] /\ bge_row m 256 (g_RR p)
  /\ wr_at asegs m (g_D p) (g_N p) /\ acc asegs m (g_D p) (g_N p).

(* [comment removed for export] *)
Definition bge_lined (p : bgp) (i : Z) : Z := g_DD p + i * g_wpld p * 4.

