(* [comment removed for export] *)
Definition bge_j_exit (p : bgp) (i : Z) (sp gp tp s0 s2 s9 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a1' a2' a6' a7' s3' s4' s5' s7' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (g_S1 p)) a0' a1' a2' (Z_to_bv 64 i) (Z_to_bv 64 (g_wplt p * 4))
                  (Z_to_bv 64 ((g_kr p + 16) / 8 + 2147450880)) a6' a7' s2 s3' s4' s5' (Z_to_bv 64 2147450880) s7' (Z_to_bv 64 (g_S8 p)) s9
                  (Z_to_bv 64 (g_PW p)) (Z_to_bv 64 (g_kr p + 16)) t3' t4' t5' t6')
             F' (Z_to_bv 64 0xc4950) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(g_DD p, g_DD p + g_ND p)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma bge_j_loop : forall (n : nat) (p : bgp) (i j : Z)
    (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a6 s2 s3 s5 s7 s9 t3 t4 t5 t6 : word) F fc (m : mem),
  Z.of_nat n = g_w p - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < g_h p -> bgp_ok p -> frm0 fc ->
  (forall m', munch [(g_DD p, g_DD p + g_ND p)] m m' -> wmono asegs m m' ->
     bge_ro p m' /\ rw_cells asegs m' (g_S1 p + 112) [C8 (Z_to_bv 64 (bge_lined p i))]) ->
  wr_at asegs m (g_DD p) (g_ND p) -> acc asegs m (g_DD p) (g_ND p) -> mem_inv asegs m ->
  evt asegs (bge_j_exit p i sp gp tp s0 s2 s9 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (g_S1 p)) a0 a1 a2 (Z_to_bv 64 i) (Z_to_bv 64 (g_wplt p * 4))
             (Z_to_bv 64 ((g_kr p + 16) / 8 + 2147450880)) a6 (Z_to_bv 64 j) s2 s3 (Z_to_bv 64 (g_D p + i * (g_wplt p * 4) + j)) s5
             (Z_to_bv 64 2147450880) s7 (Z_to_bv 64 (g_S8 p)) s9 (Z_to_bv 64 (g_PW p)) (Z_to_bv 64 (g_kr p + 16)) t3 t4 t5 t6)
        F (Z_to_bv 64 0xc4994) fc None m (seg_rom asegs)).
