(* [comment removed for export] *)
Definition bge_W1 (p : bgp) : list (Z * Z) := [(g_DD p, g_DD p + g_ND p); (g_S1 p + 64, g_S1 p + 72); (g_S1 p + 112, g_S1 p + 120)].

Definition bge_i_exit (p : bgp) (sp gp tp s0 s2 s9 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a1' a2' a3' a6' a7' s3' s4' s5' s7' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (g_S1 p)) a0' a1' a2' a3' (Z_to_bv 64 (g_wplt p * 4))
                  (Z_to_bv 64 ((g_kr p + 16) / 8 + 2147450880)) a6' a7' s2 s3' s4' s5' (Z_to_bv 64 2147450880) s7' (Z_to_bv 64 (g_S8 p)) s9
                  (Z_to_bv 64 (g_PW p)) (Z_to_bv 64 (g_kr p + 16)) t3' t4' t5' t6')
             F' (Z_to_bv 64 0xc4be8) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch (bge_W1 p) m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma bge_i_loop : forall (n : nat) (p : bgp) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a6 a7 s2 s3 s4 s5 s7 s9 t3 t4 t5 t6 x112 : word) F fc (m : mem),
  Z.of_nat n = g_h p - i -> 0 <= i -> (1 <= n)%nat -> bgp_ok p -> frm0 fc ->
  (g_S1 p + 128 <= g_DD p \/ g_DD p + g_ND p <= g_S1 p) -> (g_S1 p + 128 <= 0x7fff7000 \/ 0x10007fff8000 <= g_S1 p) ->
  (forall m', munch (bge_W1 p) m m' -> wmono asegs m m' -> bge_ro p m') ->
  rw_cells asegs m (g_S1 p + 64) [C8 (Z_to_bv 64 (g_D p + i * (g_wplt p * 4)))] -> rw_cells asegs m (g_S1 p + 112) [C8 x112] ->
  wr_at asegs m (g_DD p) (g_ND p) -> acc asegs m (g_DD p) (g_ND p) -> mem_inv asegs m ->
  evt asegs (bge_i_exit p sp gp tp s0 s2 s9 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (g_S1 p)) a0 a1 a2 (Z_to_bv 64 i) (Z_to_bv 64 (g_wplt p * 4))
             (Z_to_bv 64 ((g_kr p + 16) / 8 + 2147450880)) a6 a7 s2 s3 s4 s5
             (Z_to_bv 64 2147450880) s7 (Z_to_bv 64 (g_S8 p)) s9 (Z_to_bv 64 (g_PW p)) (Z_to_bv 64 (g_kr p + 16)) t3 t4 t5 t6)
